import { useMemo, useState } from 'react';
import { JxChip, JxProgressCircle, JxBadge, JxPagination, JxEmptyState, JxButton } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'at-risk' | 'over' | 'paused';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' | 'info' }> = {
  active: { label: 'Активен', tone: 'success' },
  'at-risk': { label: 'На грани', tone: 'warning' },
  over: { label: 'Превышен', tone: 'danger' },
  paused: { label: 'На паузе', tone: 'info' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Redesign сайта', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Мобильное приложение', quotaPercent: 88, status: 'at-risk' },
  { id: 'p3', name: 'Внутренняя аналитика', quotaPercent: 104, status: 'over' },
  { id: 'p4', name: 'Миграция инфраструктуры', quotaPercent: 15, status: 'paused' },
  { id: 'p5', name: 'Маркетинговый лендинг', quotaPercent: 67, status: 'active' },
  { id: 'p6', name: 'API для партнёров', quotaPercent: 95, status: 'at-risk' },
  { id: 'p7', name: 'Обновление дизайн-системы', quotaPercent: 30, status: 'active' },
  { id: 'p8', name: 'Поддержка legacy-модуля', quotaPercent: 120, status: 'over' },
  { id: 'p9', name: 'Онбординг сотрудников', quotaPercent: 5, status: 'paused' },
  { id: 'p10', name: 'Отчётность для инвесторов', quotaPercent: 73, status: 'active' },
  { id: 'p11', name: 'Тестовое покрытие', quotaPercent: 58, status: 'at-risk' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const removeStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses([]);
    setPage(1);
  };

  const filtered = useMemo(() => {
    if (selectedStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((p) => selectedStatuses.includes(p.status));
  }, [selectedStatuses]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4, 16px)',
        maxWidth: 640,
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-space-2, 8px)', flexWrap: 'wrap' }}>
        {(Object.keys(STATUS_META) as ProjectStatus[]).map((status) => {
          const active = selectedStatuses.includes(status);
          return (
            <JxChip
              key={status}
              active={active}
              removable={active}
              onClick={() => toggleStatus(status)}
              onRemove={() => removeStatus(status)}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Ни один проект не соответствует выбранным фильтрам."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3, 12px)' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 'var(--jx-space-4, 16px)',
                  padding: 'var(--jx-space-3, 12px)',
                  borderRadius: 'var(--jx-radius-md)',
                  background: 'var(--jx-color-surface)',
                }}
              >
                <span style={{ flex: 1, color: 'var(--jx-color-text)' }}>{project.name}</span>
                <JxProgressCircle value={Math.min(project.quotaPercent, 100)} showValue />
                <JxBadge tone={STATUS_META[project.status].tone}>{STATUS_META[project.status].label}</JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

